import pandas as pd

ref_path = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en\reference\FG_14\member_list_completed_res.xlsx"
pred_path = r"C:\Users\sandeeppawar\Downloads\aida-eval\runs\aida-ctrl\work\FG_14\member_list_completed.xlsx"

# Read both sheets
ref_df = pd.read_excel(ref_path, sheet_name='Sheet1')
pred_df = pd.read_excel(pred_path, sheet_name='Sheet1')

# Normalize for comparison
def normalize_value(val):
    if pd.isna(val) or val == "" or val is None:
        return None
    if isinstance(val, str):
        return val.strip()
    return val

# Full comparison
differences = []
for idx in range(len(ref_df)):
    for col in ref_df.columns:
        ref_val = normalize_value(ref_df.loc[idx, col])
        pred_val = normalize_value(pred_df.loc[idx, col])

        if ref_val != pred_val:
            differences.append({
                "row": idx,
                "column": col,
                "ref_value": ref_val,
                "pred_value": pred_val
            })

result = {
    "total_rows": len(ref_df),
    "total_cells": len(ref_df) * len(ref_df.columns),
    "differences_count": len(differences),
    "all_differences": differences if len(differences) <= 50 else differences[:50]
}

print(result)
